{
  "findings": [
    {
      "check_id": "CKV_AZURE_25",
      "title": "SQL Server security alert policy has alert disabled for Sql_Injection",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "CRITICAL",
      "explanation": "The security alert policy for the SQL Server has Sql_Injection alert disabled, potentially missing critical security notifications."
    },
    {
      "check_id": "CKV_AZURE_25",
      "title": "SQL Server security alert policy has alert disabled for Data_Exfiltration",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "HIGH",
      "explanation": "The security alert policy for the SQL Server has Data_Exfiltration alert disabled, potentially missing important security notifications."
    },
    {
      "check_id": "CKV_AZURE_117",
      "title": "SQL Server security alert policy stores logs in storage account with access key",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The security alert policy uses a storage account access key, which is a sensitive value that should be handled with care."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"alertpolicy6\" {\n  resource_group_name        = azurerm_resource_group.example.name\n  server_name                = azurerm_mssql_server.mssql6.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint\n  storage_account_access_key = \"\"\n  disabled_alerts = []\n  retention_days  = 30\n  email_addresses = [\"securityengineer@bridgecrew.io\", \"securityteam@bridgecrew.io\"]\n}",
  "fix_summary": "Enabled Sql_Injection and Data_Exfiltration alerts, removed storage_account_access_key, increased retention_days to 30, and added an email address to the email_addresses list."
}
